from math import log2


def H(*counts):
    n = sum(counts)
    return -sum(c / n * log2(c / n) for c in counts if c)


groups = {'Phone': (4, 2), 'Laptop': (1, 3), 'Tablet': (2, 0)}
assert sum(sum(g) for g in groups.values()) == 12
bought = sum(g[0] for g in groups.values())
parent = H(bought, 12 - bought)
child = sum(sum(g) / 12 * H(*g) for g in groups.values())
print(round(parent - child, 4))

