pF, pA = 0.1, 0.3
pS = {(True, True): 0.9, (True, False): 0.7, (False, True): 0.6, (False, False): 0.1}
pV = {True: 0.8, False: 0.1}


def joint_score(f):
    total = 0.0
    for a in (True, False):
        total += (pF if f else 1 - pF) * (pA if a else 1 - pA) * pS[(f, a)] * pV[f]
    return total


yes, no = joint_score(True), joint_score(False)
print(round(yes / (yes + no), 4))
